9	export interface AgentSession extends Trajectory {
10	  /**
11	   * Send data to the agent. Promise resolves when action is acknowledged.
12	   * Returns the `streamId` of the stream the message was correlated to -- this may
13	   * be a new stream if idle or an existing stream.
14	   */
15	  send(payload: AgentSend): Promise<{ streamId: string }>;
16	  /**
17	   * Begin listening to actively streaming data. Stream must have the following
18	   * properties:
19	   *
20	   * - If no arguments are provided, streams events from an active stream.
21	   * - If a {streamId} is provided, streams ALL events from that stream.
22	   * - If an {eventId} is provided, streams all events AFTER that event.
23	   */
24	  stream(options?: {
25	    streamId?: string;
26	    eventId?: string;
27	  }): AsyncIterableIterator<AgentEvent>;
28	
29	  /**
30	   * Aborts an active stream of agent activity.
31	   */
32	  abort(): Promise<void>;
33	
34	  /**
35	   * AgentSession implements the Trajectory interface and can retrieve existing events.
36	   */
37	  readonly events: AgentEvent[];
38	}
