58	export interface AgentEventCommon {
59	  /** Unique id for the event. */
60	  id: string;
61	  /** Identifies the subagent thread, omitted for "main thread" events. */
62	  threadId?: string;
63	  /** Identifies a particular stream of a particular thread. */
64	  streamId?: string;
65	  /** ISO Timestamp for the time at which the event occurred. */
66	  timestamp: string;
67	  /** The concrete type of the event. */
68	  type: string;
69	
70	  /** Optional arbitrary metadata for the event. */
71	  _meta?: {
72	    /** source of the event e.g. 'user' | 'ext:{ext_name}/hooks/{hook_name}' */
73	    source?: string;
74	    [key: string]: unknown;
75	  };
76	}
