78	export type AgentEventData<
79	  EventType extends keyof AgentEvents = keyof AgentEvents,
80	> = AgentEvents[EventType] & { type: EventType };
81	
82	export type AgentEvent<
83	  EventType extends keyof AgentEvents = keyof AgentEvents,
84	> = AgentEventCommon & AgentEventData<EventType>;
