86	export interface AgentEvents {
87	  /** MUST be the first event emitted in a session. */
88	  initialize: Initialize;
89	  /** Updates configuration about the current session/agent. */
90	  session_update: SessionUpdate;
91	  /** Message content provided by user, agent, or developer. */
92	  message: Message;
93	  /** Event indicating the start of a new stream. */
94	  stream_start: StreamStart;
95	  /** Event indicating the end of a running stream. */
96	  stream_end: StreamEnd;
97	  /** Tool request issued by the agent. */
98	  tool_request: ToolRequest;
99	  /** Tool update issued by the agent. */
100	  tool_update: ToolUpdate;
101	  /** Tool response supplied by the agent. */
102	  tool_response: ToolResponse;
103	  /** Elicitation request to be displayed to the user. */
104	  elicitation_request: ElicitationRequest;
105	  /** User's response to an elicitation to be returned to the agent. */
106	  elicitation_response: ElicitationResponse;
107	  /** Reports token usage information. */
108	  usage: Usage;
109	  /** Report errors. */
110	  error: ErrorData;
111	  /** Custom events for things not otherwise covered above. */
112	  custom: CustomEvent;
113	}
