22	/**
23	 * A mock implementation of AgentSession for testing.
24	 * Allows queuing responses that will be yielded when send() is called.
25	 */
26	export class MockAgentSession implements AgentSession {
27	  private _events: AgentEvent[] = [];
28	  private _responses: Array<{
29	    events: MockAgentEvent[];
30	    options?: PushResponseOptions;
31	  }> = [];
32	  private _streams = new Map<string, AgentEvent[]>();
33	  private _activeStreamIds = new Set<string>();
34	  private _lastStreamId?: string;
35	  private _nextEventId = 1;
36	  private _streamResolvers = new Map<string, Array<() => void>>();
37	
38	  title?: string;
39	  model?: string;
40	  config?: Record<string, unknown>;
41	
42	  constructor(initialEvents: AgentEvent[] = []) {
43	    this._events = [...initialEvents];
44	  }
45	
46	  /**
47	   * All events that have occurred in this session so far.
48	   */
49	  get events(): AgentEvent[] {
50	    return this._events;
51	  }
52	
53	  /**
54	   * Queues a sequence of events to be "emitted" by the agent in response to the
55	   * next send() call.
56	   */
57	  pushResponse(events: MockAgentEvent[], options?: PushResponseOptions) {
58	    // We store them as data and normalize them when send() is called
59	    this._responses.push({ events, options });
60	  }
61	
62	  /**
63	   * Appends events to an existing stream and notifies any waiting listeners.
64	   */
65	  pushToStream(
66	    streamId: string,
67	    events: MockAgentEvent[],
68	    options?: { close?: boolean },
69	  ) {
70	    const stream = this._streams.get(streamId);
71	    if (!stream) {
72	      throw new Error(`Stream not found: ${streamId}`);
73	    }
74	
75	    const now = new Date().toISOString();
76	    for (const eventData of events) {
77	      const event: AgentEvent = {
78	        ...eventData,
79	        id: eventData.id ?? `e-${this._nextEventId++}`,
80	        timestamp: eventData.timestamp ?? now,
81	        streamId: eventData.streamId ?? streamId,
82	      } as AgentEvent;
83	      stream.push(event);
84	    }
85	
86	    if (
87	      options?.close &&
88	      !events.some((eventData) => eventData.type === 'stream_end')
89	    ) {
90	      stream.push({
91	        id: `e-${this._nextEventId++}`,
92	        timestamp: now,
93	        streamId,
94	        type: 'stream_end',
95	        reason: 'completed',
96	      } as AgentEvent);
97	    }
98	
99	    this._notify(streamId);
100	  }
101	
102	  private _notify(streamId: string) {
103	    const resolvers = this._streamResolvers.get(streamId);
104	    if (resolvers) {
105	      this._streamResolvers.delete(streamId);
106	      for (const resolve of resolvers) resolve();
107	    }
108	  }
109	
110	  async send(payload: AgentSend): Promise<{ streamId: string }> {
111	    const { events: response, options } = this._responses.shift() ?? {
112	      events: [],
113	    };
114	    const streamId =
115	      response[0]?.streamId ?? `mock-stream-${this._streams.size + 1}`;
116	
117	    const now = new Date().toISOString();
118	
119	    if (!response.some((eventData) => eventData.type === 'stream_start')) {
120	      response.unshift({
121	        type: 'stream_start',
122	        streamId,
123	      });
124	    }
125	
126	    const startIndex = response.findIndex(
127	      (eventData) => eventData.type === 'stream_start',
128	    );
129	
130	    if ('message' in payload && payload.message) {
131	      response.splice(startIndex + 1, 0, {
132	        type: 'message',
133	        role: 'user',
134	        content: payload.message,
135	        _meta: payload._meta,
136	      });
137	    } else if ('elicitations' in payload && payload.elicitations) {
138	      payload.elicitations.forEach((elicitation, i) => {
139	        response.splice(startIndex + 1 + i, 0, {
140	          type: 'elicitation_response',
141	          ...elicitation,
142	          _meta: payload._meta,
143	        });
144	      });
145	    } else if ('update' in payload && payload.update) {
146	      if (payload.update.title) this.title = payload.update.title;
147	      if (payload.update.model) this.model = payload.update.model;
148	      if (payload.update.config) {
149	        this.config = payload.update.config;
150	      }
151	      response.splice(startIndex + 1, 0, {
152	        type: 'session_update',
153	        ...payload.update,
154	        _meta: payload._meta,
155	      });
156	    } else if ('action' in payload && payload.action) {
157	      throw new Error(
158	        `Actions not supported in MockAgentSession: ${payload.action.type}`,
159	      );
160	    }
161	
162	    if (
163	      !options?.keepOpen &&
164	      !response.some((eventData) => eventData.type === 'stream_end')
165	    ) {
166	      response.push({
167	        type: 'stream_end',
168	        reason: 'completed',
169	        streamId,
170	      });
171	    }
172	
173	    const normalizedResponse: AgentEvent[] = [];
174	    for (const eventData of response) {
175	      const event: AgentEvent = {
176	        ...eventData,
177	        id: eventData.id ?? `e-${this._nextEventId++}`,
178	        timestamp: eventData.timestamp ?? now,
179	        streamId: eventData.streamId ?? streamId,
180	      } as AgentEvent;
181	      normalizedResponse.push(event);
182	    }
183	
184	    this._streams.set(streamId, normalizedResponse);
185	    this._activeStreamIds.add(streamId);
186	    this._lastStreamId = streamId;
187	
188	    return { streamId };
189	  }
